import{_ as l,a as r,l as e,u as i,v as s,w as _,x as n,y as g,z as c,A as o,b as a,c as u,d as p,e as B,f,g as N,h as d,i as A,j as z,k as Z,m as L,n as m,o as b,p as h,q as D,r as y,s as v,t as M}from"./chunks/load3d_l12l0a_nc1hwc02nz.CtmH8dYx.js";import{_ as P,o as I,a as x,b as C}from"./app.BZuKQ50m.js";const W=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算搬运","link":"/api/SIMD-API/c_api/cube_datamove/cube_datamove"},{"text":"矩阵计算输入搬运约束","link":"/api/SIMD-API/c_api/cube_datamove/cube_compute_input_move_constraint"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_datamove/cube_compute_input_move_constraint.md","filePath":"api/SIMD-API/c_api/cube_datamove/cube_compute_input_move_constraint.md","outlineHeaders":[{"level":2,"title":"对齐约束","slug":"对齐约束","link":"#对齐约束"},{"level":2,"title":"搬运粒度约束","slug":"搬运粒度约束","link":"#搬运粒度约束"},{"level":2,"title":"分形约束","slug":"分形约束","link":"#分形约束"},{"level":3,"title":"针对Atlas A2训练系列产品/Atlas A2推理系列产品和Atlas A3训练系列产品/Atlas A3推理系列产品","slug":"针对Atlas-A2训练系列产品/Atlas-A2推理系列产品和Atlas-A3训练系列产品/Atlas-A3推理系列产品","link":"#针对Atlas-A2训练系列产品/Atlas-A2推理系列产品和Atlas-A3训练系列产品/Atlas-A3推理系列产品"},{"level":3,"title":"针对Ascend 950PR/Ascend 950DT","slug":"针对Ascend-950PR/Ascend-950DT","link":"#针对Ascend-950PR/Ascend-950DT"},{"level":2,"title":"数据类型约束","slug":"数据类型约束","link":"#数据类型约束"},{"level":2,"title":"搬运指令总结","slug":"搬运指令总结","link":"#搬运指令总结"}],"lastUpdated":1789544578000}'),k={name:"api/SIMD-API/c_api/cube_datamove/cube_compute_input_move_constraint.md"};function S(T,t,R,E,G,w){return I(),x("div",null,[...t[0]||(t[0]=[C('<div><article class="markdown-body"><h1>矩阵计算输入搬运约束</h1><h2 id="对齐约束">对齐约束<a class="header-anchor" href="#对齐约束">​</a></h2><p>具体可见<a href="../general_description_and_constraints.html#%E5%AD%98%E5%82%A8%E5%8D%95%E5%85%83%E8%AF%B4%E6%98%8E">存储单元说明</a>。</p><ul><li>当源地址位于L1 Buffer时，该地址必须32Byte对齐；当源地址位于GM时，该地址必须1Byte对齐。</li><li>当目的地址位于L0A Buffer/L0B Buffer时，该地址必须512Byte对齐；当目的地址位于L1 Buffer时，该地址必须32Byte对齐。</li></ul><h2 id="搬运粒度约束">搬运粒度约束<a class="header-anchor" href="#搬运粒度约束">​</a></h2><ul><li>2D矩阵搬运以大小为512Byte的分形为单位进行搬运。</li><li>3D矩阵搬运以大小为512Byte的分形为单位进行搬运。</li></ul><div data-filter="910b,A3"><ul><li>asc_copy_l12l0b_sparse搬运以512Byte为单位存放的压缩权重矩阵到L0B Buffer里，同时搬运以128Byte为单位的索引矩阵到内置的专用buffer空间。</li></ul></div><h2 id="分形约束">分形约束<a class="header-anchor" href="#分形约束">​</a></h2><p>数据搬运（GM-&gt;L1 Buffer）在不使能随路进行ND到Nz转换的时候，不会改变分形间和分形内排布，如Nz2Nz，在使能ND到Nz转换的情况下，一定会改变分形排布，如ND2Nz。</p><p>2D矩阵搬运在不使能转置情况下，只能改变分形间的排布，如Nz2Zz；在使能转置情况下，既能改变分形内的排布，又能改变分形间的排布，如Nz2Zn。</p><p>转置搬运一定改变分形内的排布，可以按需改变分形间的排布，如Nz2Zn。</p><p>转置搬运在B32场景下，源操作数2个连续的16*8分形将被合并为1个16*16的方块矩阵，然后再基于该方块矩阵做转置，因此要求两个连续分形合并为方块矩阵，要求L1 Buffer上的矩阵满足Nz排布（当且仅当Row==16）或Zn排布（当且仅当Col==16）。</p><p>3D矩阵搬运主要用于对NC1HWC0格式的feature map完成image to column操作，并将展开后的二维矩阵搬入对应内存位置，因此对于3D矩阵搬运的源操作数中数据必须按照NC1HWC0格式排布，目的操作数数据必须按照目的地址L0A Buffer/L0B Buffer中支持的排布方式排布。</p><div data-filter="910b,A3"><p>asc_copy_l12l0b_sparse主要用于搬运以512Byte为单位存放的压缩权重矩阵到L0B Buffer里，同时搬运以128Byte为单位的索引矩阵到内置的专用buffer空间（用于后续asc_mmad_sparse接口进行读取），因此源操作数中的压缩权重矩阵和索引矩阵都需要按照Zn格式排布，其中压缩权重矩阵排布方式为32*16*8bit=512Byte，索引矩阵排布方式为32*16*2bit=128Byte。</p></div><p>矩阵计算过程中，常用分形支持总结如下表：</p><div data-filter="910b,A3"><h3 id="针对Atlas-A2训练系列产品/Atlas-A2推理系列产品和Atlas-A3训练系列产品/Atlas-A3推理系列产品">针对Atlas A2训练系列产品/Atlas A2推理系列产品和Atlas A3训练系列产品/Atlas A3推理系列产品<a class="header-anchor" href="#针对Atlas-A2训练系列产品/Atlas-A2推理系列产品和Atlas-A3训练系列产品/Atlas-A3推理系列产品">​</a></h3><p>常用分形支持情况如下，供开发者参考：</p><ul><li><strong>数据搬运</strong><ul><li>GM-&gt;L1 Buffer <ul><li><p>ND-&gt;Nz：</p><p><img src="'+l+'" alt></p></li><li><p>Nz-&gt;Nz：</p><p><img src="'+r+'" alt></p></li><li><p>Zn-&gt;Zn：</p><p><img src="'+e+'" alt></p></li></ul></li></ul></li><li><strong>2D矩阵搬运</strong><ul><li><p>GM-&gt;L1 Buffer（不支持转置）</p><ul><li><p>Nz-&gt;Nz：</p><p><img src="'+i+'" alt></p></li><li><p>Zn-&gt;Zn：</p><p><img src="'+s+'" alt></p></li></ul></li><li><p>GM-&gt;L0A Buffer（不支持转置）L1 Buffer-&gt;L0A Buffer（不使能转置）（Nz-&gt;Zz）</p><p><img src="'+_+'" alt></p></li><li><p>GM-&gt;L0B Buffer（不支持转置）L1 Buffer-&gt;L0B Buffer（不使能转置）（Zn-&gt;Zn）</p><p><img src="'+n+'" alt></p></li><li><p>L1 Buffer-&gt;L0A Buffer（使能转置，仅支持b16数据类型）（Nz-&gt;Zz）</p><p><img src="'+g+'" alt></p></li><li><p>L1 Buffer-&gt;L0B Buffer（使能转置，仅支持b16数据类型）（Zn-&gt;Zn）</p><p><img src="'+c+'" alt></p></li></ul></li><li><strong>转置搬运</strong><ul><li><p>L1 Buffer-&gt;L0A Buffer（b8）（Nz-&gt;Zz）</p><p><img src="'+o+'" alt></p></li><li><p>L1 Buffer-&gt;L0B Buffer（b4/b8）（Zn-&gt;Zn）</p><p><img src="'+a+'" alt></p></li><li><p>L1 Buffer-&gt;L0A Buffer（b16）（Nz-&gt;Zz）</p><p><img src="'+u+'" alt></p></li><li><p>L1 Buffer-&gt;L0B Buffer（b16）（Zn-&gt;Zn）</p><p><img src="'+p+'" alt></p></li><li><p>L1 Buffer-&gt;L0A Buffer（b32）（Nz（<span>当且仅当Row==16</span>）-&gt;Zz）</p><p><img src="'+B+'" alt></p></li><li><p>L1 Buffer-&gt;L0B Buffer（b32）（Zn（<span>当且仅当Col==16</span>）-&gt;Zn）</p><p><img src="'+f+'" alt></p></li></ul></li><li><strong>3D矩阵搬运</strong><ul><li><p>L1 Buffer-&gt;L0A Buffer（NC1HWC0-&gt;Zz）</p><p><img src="'+N+'" alt></p></li><li><p>L1 Buffer-&gt;L0B Buffer（NC1HWC0-&gt;Zn）</p><p><img src="'+d+'" alt></p></li></ul></li><li><strong>asc_copy_l12l0b_sparse</strong><ul><li><p>L1 Buffer-&gt;L0B Buffer（Zn-&gt;Zn）</p><p><img src="'+A+'" alt></p></li></ul></li></ul><p>针对一些不常用的分形转换的支持情况，开发者可参考下表：</p><p><strong>表1</strong> 扩展分形转换支持情况</p><table><thead><tr><th>搬运指令</th><th>数据通路</th><th>分形支持情况</th></tr></thead><tbody><tr><td>2D分形搬运</td><td>GM-&gt;L1 Buffer（不支持转置）</td><td>Nz-&gt;Zz、Zn-&gt;Nn、Zz-&gt;Zz、Zz-&gt;Nz、Nn-&gt;Nn、Nn-&gt;Zn</td></tr><tr><td>2D分形搬运</td><td>GM-&gt;L0A Buffer（不支持转置）、<br>L1 Buffer-&gt;L0A Buffer（不使能转置）</td><td>Nz-&gt;Nz、Zn-&gt;Nn、Zn-&gt;Zn、Zz-&gt;Zz、Zz-&gt;Nz、Nn-&gt;Nn、Nn-&gt;Zn</td></tr><tr><td>2D分形搬运</td><td>GM-&gt;L0B Buffer（不支持转置）、<br>L1 Buffer-&gt;L0B Buffer（不使能转置）</td><td>Nz-&gt;Zz、Nz-&gt;Nz、Zn-&gt;Nn、Zz-&gt;Zz、Zz-&gt;Nz、Nn-&gt;Nn、Nn-&gt;Zn</td></tr><tr><td>2D分形搬运</td><td>L1 Buffer-&gt;L0A Buffer（使能转置，仅支持b16数据类型）</td><td>Nz-&gt;Nz、Zn-&gt;Nn、Zn-&gt;Zn、Zz-&gt;Zz、Zz-&gt;Nz、Nn-&gt;Nn、Nn-&gt;Zn</td></tr><tr><td>2D分形搬运</td><td>L1 Buffer-&gt;L0B Buffer（使能转置，仅支持b16数据类型）</td><td>Nz-&gt;Zz、Nz-&gt;Nz、Zn-&gt;Nn、Zz-&gt;Zz、Zz-&gt;Nz、Nn-&gt;Nn、Nn-&gt;Zn</td></tr><tr><td>块转置搬运</td><td>L1 Buffer-&gt;L0A Buffer（b8）、<br>L1 Buffer-&gt;L0A Buffer（b16）</td><td>Nz-&gt;Nz、Zn-&gt;Nn、Zn-&gt;Zn、Zz-&gt;Zz、Zz-&gt;Nz、Nn-&gt;Nn、Nn-&gt;Zn</td></tr><tr><td>块转置搬运</td><td>L1 Buffer-&gt;L0B Buffer（b4/b8）、<br>L1 Buffer-&gt;L0B Buffer（b16）</td><td>Nz-&gt;Zz、Nz-&gt;Nz、Zn-&gt;Nn、Zz-&gt;Zz、Zz-&gt;Nz、Nn-&gt;Nn、Nn-&gt;Zn</td></tr><tr><td>块转置搬运</td><td>L1 Buffer-&gt;L0A Buffer（b32）</td><td>Zz-&gt;Nz、Zz-&gt;Zz</td></tr><tr><td>块转置搬运</td><td>L1 Buffer-&gt;L0B Buffer（b32）</td><td>Nn-&gt;Zn、Nn-&gt;Nn</td></tr></tbody></table></div><div data-filter="950"><h3 id="针对Ascend-950PR/Ascend-950DT">针对Ascend 950PR/Ascend 950DT<a class="header-anchor" href="#针对Ascend-950PR/Ascend-950DT">​</a></h3><p>数据搬运（GM-&gt;L1 Buffer）支持使能随路进行DN到Nz转换，一定会改变分形排布。</p><p>2D矩阵搬运在不使能转置情况下，不改变分形间排布及分形内的排布，如Nz2Nz；在使能转置情况下，既改变分形内的排布，又改变分形间的排布，如Nz2Zn。</p><p>MX矩阵的数据和系数分别搬运：A/B数据使用普通2D重载或<code>_transpose</code>变体；<code>asc_copy_l12l0a_mx</code>/<code>asc_copy_l12l0b_mx</code>只搬运E8M0系数，不提供矩阵数据搬运或转置开关。系数需预先按对应布局准备，系数搬运本身不改变分形内排布。</p><p>常用分形支持情况如下，供开发者参考：</p><ul><li><strong>数据搬运</strong><ul><li>GM-&gt;L1 Buffer <ul><li><p>ND-&gt;Nz：</p><p><img src="'+l+'" alt></p></li><li><p>DN-&gt;Nz：</p><p><img src="'+z+'" alt></p></li><li><p>Nz-&gt;Nz：</p><p><img src="'+r+'" alt></p></li><li><p>Zn-&gt;Zn：</p><p><img src="'+e+'" alt></p></li></ul></li></ul></li><li><strong>2D矩阵搬运</strong><ul><li><p>L1 Buffer-&gt;L0A Buffer（Nz-&gt;Nz）</p><p><img src="'+Z+'" alt></p></li><li><p>L1 Buffer-&gt;L0A Buffer（使能转置）（Zn-&gt;Nz）</p><p><img src="'+L+'" alt></p></li><li><p>L1 Buffer-&gt;L0B Buffer（Zn-&gt;Zn）</p><p><img src="'+m+'" alt></p></li><li><p>L1 Buffer-&gt;L0B Buffer（使能转置）（Nz-&gt;Zn）</p><p><img src="'+b+'" alt></p></li></ul></li><li><strong>MX数据与系数的独立搬运</strong><ul><li><p>L1 Buffer-&gt;L0A Buffer（数据，调用asc_copy_l12l0a，Nz-&gt;Nz）</p><p><img src="'+h+'" alt></p></li><li><p>L1 Buffer-&gt;L0A_MX Buffer（系数，调用asc_copy_l12l0a_mx）</p><p><img src="'+D+'" alt></p></li><li><p>L1 Buffer-&gt;L0B Buffer（数据，调用asc_copy_l12l0b，Zn-&gt;Zn）</p><p><img src="'+y+'" alt></p></li><li><p>L1 Buffer-&gt;L0B_MX Buffer（系数，调用asc_copy_l12l0b_mx）</p><p><img src="'+v+'" alt></p></li></ul></li><li><strong>转置搬运</strong><ul><li><p>L1 Buffer-&gt;L0B Buffer（b4/b8）（Zn-&gt;Zn）</p><p><img src="'+a+'" alt></p></li><li><p>L1 Buffer-&gt;L0B Buffer（b16）（Zn-&gt;Zn）</p><p><img src="'+p+'" alt></p></li><li><p>L1 Buffer-&gt;L0B Buffer（b32）（Zn（<span>当且仅当Col==16</span>）-&gt;Zn）</p><p><img src="'+f+'" alt></p></li></ul></li><li><strong>3D矩阵搬运</strong><ul><li><p>L1 Buffer-&gt;L0A Buffer（NC1HWC0-&gt;Nz）</p><p><img src="'+M+'" alt></p></li><li><p>L1 Buffer-&gt;L0B Buffer（NC1HWC0-&gt;Zn）</p><p><img src="'+d+'" alt></p></li></ul></li></ul><p>针对一些不常用的分形转换的支持情况，开发者可参考下表：</p><p><strong>表2</strong> 扩展分形转换支持情况</p><table><thead><tr><th>搬运指令</th><th>数据通路</th><th>分形支持情况</th></tr></thead><tbody><tr><td>2D矩阵搬运</td><td>GM-&gt;L1 Buffer（不支持转置）</td><td>Nz-&gt;Zz、Zn-&gt;Nn、Zz-&gt;Zz、Zz-&gt;Nz、Nn-&gt;Nn、Nn-&gt;Zn</td></tr><tr><td>2D矩阵搬运</td><td>L1 Buffer-&gt;L0A Buffer（不使能转置）</td><td>Nz-&gt;Nz、Zn-&gt;Nn、Zn-&gt;Zn、Zz-&gt;Zz、Zz-&gt;Nz、Nn-&gt;Nn、Nn-&gt;Zn</td></tr><tr><td>2D矩阵搬运</td><td>L1 Buffer-&gt;L0B Buffer（不使能转置）</td><td>Nz-&gt;Zz、Nz-&gt;Nz、Zn-&gt;Nn、Zz-&gt;Zz、Zz-&gt;Nz、Nn-&gt;Nn、Nn-&gt;Zn</td></tr><tr><td>2D矩阵搬运</td><td>L1 Buffer-&gt;L0A Buffer（使能转置，图中以b16为例）</td><td>Nz-&gt;Nz、Zn-&gt;Nn、Zn-&gt;Zn、Zz-&gt;Zz、Zz-&gt;Nz、Nn-&gt;Nn、Nn-&gt;Zn</td></tr><tr><td>2D矩阵搬运</td><td>L1 Buffer-&gt;L0B Buffer（使能转置，图中以b16为例）</td><td>Nz-&gt;Zz、Nz-&gt;Nz、Zn-&gt;Nn、Zz-&gt;Zz、Zz-&gt;Nz、Nn-&gt;Nn、Nn-&gt;Zn</td></tr><tr><td>转置搬运</td><td>L1 Buffer-&gt;L0B Buffer（b4/b8）、<br>L1 Buffer-&gt;L0B Buffer（b16）</td><td>Nz-&gt;Zz、Nz-&gt;Nz、Zn-&gt;Nn、Zz-&gt;Zz、Zz-&gt;Nz、Nn-&gt;Nn、Nn-&gt;Zn</td></tr><tr><td>转置搬运</td><td>L1 Buffer-&gt;L0B Buffer（b32）</td><td>Nn-&gt;Zn、Nn-&gt;Nn</td></tr></tbody></table></div><h2 id="数据类型约束">数据类型约束<a class="header-anchor" href="#数据类型约束">​</a></h2><div data-filter="910b,A3"><p>针对Atlas A2训练系列产品/Atlas A2推理系列产品和Atlas A3训练系列产品/Atlas A3推理系列产品，数据类型约束如表3所示：</p><p><strong>表3</strong> 数据类型约束</p><table><thead><tr><th>接口/重载</th><th>C API指针类型</th></tr></thead><tbody><tr><td><code>asc_copy_gm2l1</code>分形搬运</td><td>half、bfloat16_t、int8_t、uint8_t、int32_t、uint32_t、float</td></tr><tr><td><code>asc_copy_gm2l0a</code>/<code>asc_copy_gm2l0b</code>；<code>asc_copy_l12l0a</code>/<code>asc_copy_l12l0b</code>的2D重载</td><td>上述类型及int4b_t；具体搬运位宽和转置限制仍按各接口</td></tr><tr><td><code>asc_copy_l12l0a_trans</code> / <code>asc_copy_l12l0b_trans</code></td><td>half、bfloat16_t、int8_t、uint8_t、int32_t、uint32_t、float</td></tr><tr><td><code>asc_copy_l12l0b_sparse</code></td><td>int8_t权重及对应索引</td></tr><tr><td><code>asc_copy_l12l0a</code>的3D重载</td><td>half、bfloat16_t、int8_t、uint8_t、int4b_t、int32_t、uint32_t、float</td></tr><tr><td><code>asc_copy_l12l0b</code>的3D重载</td><td>half、bfloat16_t、int32_t、uint32_t、float</td></tr></tbody></table></div><div data-filter="950"><p>针对Ascend 950PR/Ascend 950DT，数据类型约束如表4所示：</p><p><strong>表4</strong> 数据类型约束</p><table><thead><tr><th>接口/重载</th><th>C API指针类型</th></tr></thead><tbody><tr><td><code>asc_copy_gm2l1</code>的2D重载</td><td>int8_t、uint8_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、fp4x2_e1m2_t、fp4x2_e2m1_t、fp8_e4m3fn_t、fp8_e5m2_t、hifloat8_t；另有void位宽搬运重载</td></tr><tr><td><code>asc_copy_l12l0a</code>/<code>asc_copy_l12l0b</code>的2D重载及<code>_transpose</code></td><td>上述有类型重载及int4b_t</td></tr><tr><td><code>asc_copy_l12l0b_trans</code></td><td>int8_t、uint8_t、half、bfloat16_t、int32_t、uint32_t、float、int4b_t、fp4x2_e1m2_t、fp4x2_e2m1_t、fp8_e4m3fn_t、fp8_e5m2_t、hifloat8_t</td></tr><tr><td><code>asc_copy_l12l0a</code>/<code>asc_copy_l12l0b</code>的3D重载</td><td>int8_t、uint8_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、fp8_e4m3fn_t、fp8_e5m2_t、hifloat8_t</td></tr><tr><td><code>asc_copy_l12l0a_mx</code>/<code>asc_copy_l12l0b_mx</code></td><td>fp8_e8m0_t系数；32B分形，不搬A/B数据</td></tr></tbody></table></div><h2 id="搬运指令总结">搬运指令总结<a class="header-anchor" href="#搬运指令总结">​</a></h2><div data-filter="910b,A3"><p>结合上述数据类型与分形等约束条件，我们对数据搬入接口的使用场景进行了归纳总结，现提供如下，供开发者参考。</p><p>针对Atlas A2训练系列产品/Atlas A2推理系列产品和Atlas A3训练系列产品/Atlas A3推理系列产品，<strong>从L1 Buffer-&gt;L0A Buffer/L0B Buffer通路，常用的搬运指令有2D分形搬运、块转置搬运和asc_copy_l12l0a/asc_copy_l12l0b（3D），可以调用指令总结如表5所示：</strong></p><p><strong>表5</strong> L1 Buffer-&gt;L0A Buffer/L0B Buffer通路调用指令总结</p><table><thead><tr><th>是否转置/数据类型</th><th>b4（int4b_t）</th><th>b8</th><th>b16</th><th>b32</th></tr></thead><tbody><tr><td>A不转置（L1 Buffer-&gt;L0A Buffer不需要使能转置）</td><td>asc_copy_l12l0a（3D）</td><td>2D分形搬运、asc_copy_l12l0a（3D）（推荐使用）</td><td>2D分形搬运、asc_copy_l12l0a（3D）（推荐使用）</td><td>2D分形搬运、asc_copy_l12l0a（3D）（推荐使用）</td></tr><tr><td>A转置（L1 Buffer-&gt;L0A Buffer需要使能转置）</td><td>不支持</td><td>块转置搬运</td><td>2D分形搬运、块转置搬运、asc_copy_l12l0a（3D）（推荐使用）</td><td>块转置搬运（L1 Buffer上数据排布为Nz排布（当且仅当Row==16））、asc_copy_l12l0a（3D）（推荐使用）</td></tr><tr><td>B不转置（L1 Buffer-&gt;L0B Buffer需要使能转置）</td><td>当前公开C API无对应int4块转置重载</td><td>块转置搬运</td><td>2D分形搬运、块转置搬运、asc_copy_l12l0b（3D）（推荐使用）</td><td>块转置搬运（L1 Buffer上数据排布为Zn排布（当且仅当Col==16））、asc_copy_l12l0b（3D）（推荐使用）</td></tr><tr><td>B转置（L1 Buffer-&gt;L0B Buffer不需要使能转置）</td><td>-</td><td>2D分形搬运</td><td>2D分形搬运</td><td>2D分形搬运</td></tr></tbody></table><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><ul><li>由于2D分形搬运和块转置搬运在搬运过程中只能在一个方向做repeat搬运，涉及多个方向的数据块的搬运就需要使用for循环进行搬运，而asc_copy_l12l0a/asc_copy_l12l0b（3D）可以通过配置m_extension和k_extension来完成多个方向的数据块搬运，不需要使用for循环，因此整体的scalar开销要比2D分形搬运和块转置搬运要少，因此，在满足asc_copy_l12l0a/asc_copy_l12l0b（3D）使用约束条件的场景下，推荐使用asc_copy_l12l0a/asc_copy_l12l0b（3D）指令来实现L1 Buffer-&gt;L0A Buffer/L0B Buffer的数据搬运。</li></ul></div></div><div data-filter="950"><p>针对Ascend 950PR/Ascend 950DT，asc_copy_l12l0a/asc_copy_l12l0b（2D）可以支持b4（fp4）/b8/b16/b32数据类型以及转置场景搬运，通过配置m_step和k_step来完成多个方向的数据块搬运，并且相比asc_copy_l12l0a/asc_copy_l12l0b（3D），指令的带宽延时更小，因此不带量化系数的矩阵乘法过程中L1 Buffer-&gt;L0A Buffer/L0B Buffer通路，都推荐使用asc_copy_l12l0a/asc_copy_l12l0b（2D）指令来实现数据搬运。而带量化系数的矩阵乘法过程中，需要使用asc_copy_l12l0a_mx/asc_copy_l12l0b_mx（系数搬运）指令来实现数据搬运，其中A/B仍由2D接口搬入；MX接口只完成L1 Buffer-&gt;L0A_MX Buffer/L0B_MX Buffer系数搬运，两类接口需分别调用。</p></div></article></div>',1)])])}const $=P(k,[["render",S]]);export{W as __pageData,$ as default};
